const NUTRITION_SCRIPT = String.raw`
const el=(id)=>document.getElementById('nutrition-'+id);const meals={breakfast:'早餐',lunch:'午餐',dinner:'晚餐',snack:'加餐'};const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const state={date:'',today:'',includeDeleted:false,data:null,sequence:0,controller:null,busy:false,form:null,formSequence:0,trigger:null,pending:null,pendingError:'',batchPending:null,batchRows:[],batchError:'',favorites:[],draft:null,reviewDays:7,reviewSequence:0,foodResults:[],foodSequence:0};const dialog=el('dialog');const pendingKey='jiashu-nutrition-create:'+encodeURIComponent(ownerId);const batchKey='jiashu-nutrition-batch:'+encodeURIComponent(ownerId);
const esc=(value)=>String(value??'').replace(/[&<>"']/g,(char)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function validDay(value){if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value)||value<'1970-01-01'||value>'2100-12-31')return false;const time=Date.parse(value+'T12:00:00Z');return Number.isFinite(time)&&new Date(time).toISOString().slice(0,10)===value;}
function today(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=(key)=>parts.find((part)=>part.type===key).value;return get('year')+'-'+get('month')+'-'+get('day');}
const shift=(day,count)=>new Date(Date.parse(day+'T12:00:00Z')+count*86400000).toISOString().slice(0,10);
function kcal(value){if(typeof value!=='string'||!/^\d+(?:\.\d)?$/.test(value))return '—';const [whole,fraction]=value.split('.');return whole.replace(/\B(?=(\d{3})+(?!\d))/g,',')+(fraction===undefined?'':'.'+fraction);}
function calories(raw){if(raw===null||raw===undefined||(typeof raw==='string'&&!raw.trim()))return null;if(typeof raw!=='string'||raw.length>128||!/^\d+(?:\.\d)?$/.test(raw.trim()))throw new Error('热量需为0至20,000 kcal的数值，最多1位小数；未知请留空。');const parts=raw.trim().split('.');const value=BigInt(parts[0]+(parts[1]||'').padEnd(1,'0'));if(value>200000n)throw new Error('这份食物总热量不能超过20,000 kcal。');const digits=value.toString().padStart(2,'0');return digits.slice(0,-1)+'.'+digits.slice(-1);}
function text(raw,label,max,required=false){if(typeof raw!=='string')throw new Error('请填写'+label+'。');const value=raw.trim();const invalid=label==='备注'?/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/:/[\u0000-\u001f\u007f]/;if((required&&!value)||value.length>max||invalid.test(value))throw new Error(label+'需'+(required?'填写且':'')+'不超过'+max+'个字符，不能包含不支持的控制字符。');return value;}
function path(){const params=new URLSearchParams({date:state.date});if(state.includeDeleted)params.set('includeDeleted','1');return '/health/nutrition?'+params;}
const loginLink=()=>'/signin-with-chatgpt?return_to='+encodeURIComponent(path());
function storedBody(body){if(!body||!validDay(body.date)||!Object.hasOwn(meals,body.meal))throw new Error('原提交信息无效，请先核对记录。');const normalized={date:body.date,meal:body.meal,name:text(body.name,'食物名称',100,true),portion:text(body.portion,'份量',100),calories:calories(body.calories),note:text(body.note,'备注',500)};if(body.food){if(typeof body.food.id!=='string'||body.food.id.length>120||!Number.isFinite(body.food.amount)||body.food.amount<=0||typeof body.food.unit!=='string'||body.food.unit.length>20)throw new Error('原食物库份量信息无效。');normalized.food={id:body.food.id,amount:body.food.amount,unit:body.food.unit};}return normalized;}
function readPending(){const raw=sessionStorage.getItem(pendingKey);if(!raw)return null;const operation=JSON.parse(raw);if(!uuid.test(operation?.key))throw new Error('上次新增的确认信息暂时无法读取，请先核对记录。');return {key:operation.key,body:storedBody(operation.body)};}
function readBatchPending(){const raw=sessionStorage.getItem(batchKey);if(!raw)return null;const operation=JSON.parse(raw);if(!uuid.test(operation?.key)||!Array.isArray(operation?.body?.entries)||!operation.body.entries.length||operation.body.entries.length>30)throw new Error('上次批量新增的确认信息暂时无法读取，请先核对记录。');return {key:operation.key,body:{entries:operation.body.entries.map(storedBody)}};}
function setPending(operation){sessionStorage.setItem(pendingKey,JSON.stringify(operation));state.pending=Object.freeze({key:operation.key,body:Object.freeze({...operation.body})});renderPending();}
function clearPending(){sessionStorage.removeItem(pendingKey);state.pending=null;renderPending();}
function frozen(){return state.form?.mode==='create'&&Boolean(state.pending);}
function renderPending(){const blocked=state.pending||state.batchPending;el('pending').hidden=!blocked&&!state.pendingError&&!state.batchRows.length;el('pending-text').textContent=state.pendingError||(state.batchPending?'有一批食物待确认，原内容已固定；重试不会重复新增。':state.pending?'有一条新增食物待确认，原内容已固定；重试不会新增第二条。':state.batchRows.length?'有 '+state.batchRows.length+' 项食物草稿待保存，保留原日期和餐次。':'');el('resume').hidden=!state.pending;el('resume').disabled=state.busy;el('resume-batch').hidden=!state.batchPending&&!state.batchRows.length;el('resume-batch').textContent=state.batchPending?'继续确认原批次':'继续核对食物草稿';el('resume-batch').disabled=state.busy;el('add').textContent=state.batchPending?'继续确认原批次':state.pending?'继续确认原新增':'添加食物';el('add').disabled=state.busy||Boolean(state.pendingError);el('ai-parse').disabled=state.busy||Boolean(blocked)||Boolean(state.pendingError)||state.batchRows.length>0;el('ai-text').disabled=state.busy;el('ai-meal').disabled=state.busy;el('day-complete').disabled=state.busy||!state.data||state.data.date!==state.date;}
function controls(){el('quick-list').querySelectorAll('button').forEach((button)=>button.disabled=state.busy);el('day').value=state.date;el('day').max=state.today||today();el('previous').disabled=state.busy||state.date<='1970-01-01';el('next').disabled=state.busy||state.date>=(state.today||today());el('day').disabled=state.busy;el('today').disabled=state.busy;el('include-deleted').checked=state.includeDeleted;el('include-deleted').disabled=state.busy;el('list').querySelectorAll('button').forEach((button)=>button.disabled=state.busy);if(location.pathname+location.search!==path())history.replaceState(null,'',path());renderPending();}
function status(message,error=false,login=false){el('status').hidden=!message;el('status').classList.toggle('error',error);el('status-text').textContent=message;el('retry').hidden=!error;el('login').hidden=!login;el('login').href=loginLink();}
async function request(url,options={}){let response;try{response=await fetch(url,{credentials:'same-origin',cache:'no-store',redirect:'error',...options,headers:{Accept:'application/json',...options.headers}});}catch(error){if(error?.name==='AbortError')throw error;throw new Error('网络请求未完成，请检查连接后重试。');}let data;try{data=await response.json();}catch{if(response.ok)throw new Error('未收到完整确认，请重试原操作。');data={error:response.status===401?'登录已过期，请重新登录。':'服务暂时无法读取，请重试。'};}if(!response.ok){const error=new Error(typeof data?.error==='string'?data.error:'操作未完成，请重试。');error.status=response.status;error.code=data?.code;error.issues=data?.issues;throw error;}return data;}
function summaryLabel(summary){if(!summary.entryCount)return '暂无记录';if(!summary.knownCount)return '热量未填';return '已填 '+kcal(summary.knownCalories)+' kcal'+(summary.unknownCount?' · '+summary.unknownCount+'项未填':'');}
function renderSummary(){const summary=state.data.summary;const unknown=summary.entryCount>0&&summary.knownCount===0;el('summary').innerHTML='<article class="nt-card"><h2>已记录摄入热量</h2><div class="nt-number'+(!summary.entryCount||unknown?' empty':'')+'" id="nutrition-total">'+(!summary.entryCount?'暂无记录':unknown?'—':kcal(summary.knownCalories)+' kcal')+'</div><p>'+(!summary.entryCount?'还没有记录食物。':unknown?'已记录'+summary.entryCount+'项，热量均未填写。':'已填'+summary.knownCount+'项热量'+(summary.unknownCount?'；'+summary.unknownCount+'项热量未填。':'。'))+'</p></article><article class="nt-card"><h2>已记录食物</h2><div class="nt-number" id="nutrition-count">'+summary.entryCount+' 项</div><p>按本日未删除的记录计数。</p></article><article class="nt-card"><h2>热量未填</h2><div class="nt-number" id="nutrition-unknown">'+summary.unknownCount+' 项</div><p>未知热量保持为空，不按0计算。</p></article>';}
function renderWeek(){const data=state.data;el('week-range').textContent=data.recentFrom+' — '+data.recentTo;el('week').innerHTML=data.recent7days.map((day)=>{const label=day.date+'，'+summaryLabel(day.summary)+'，'+day.summary.entryCount+'项食物';return '<button class="nt-week-day" type="button" data-nutrition-date="'+day.date+'" aria-label="'+esc(label)+'" aria-pressed="'+String(day.date===state.date)+'"'+(!validDay(day.date)||day.date>state.today?' disabled':'')+'><span>'+day.date.slice(5)+'</span><strong>'+(!day.summary.entryCount?'暂无记录':day.summary.knownCount?kcal(day.summary.knownCalories)+' kcal':'热量未填')+'</strong><span>'+day.summary.entryCount+' 项'+(day.summary.unknownCount?' · '+day.summary.unknownCount+'项未填':'')+'</span></button>';}).join('');}
function sourceText(food){return food?.source?food.source.name+' · '+food.source.version+(food.estimated?' · 份量估算':''):'';}
function renderMeals(){const data=state.data,states=data.dayStatus?.meals||{};el('list').innerHTML=Object.entries(meals).map(([meal,label])=>{const entries=data.entries.filter((entry)=>entry.meal===meal);const summary=data.summary.meals.find((item)=>item.meal===meal);const active=entries.filter((entry)=>!entry.deleted);const mealState=active.length?'recorded':states[meal]||'unrecorded';const rows=entries.map((entry)=>'<li class="nt-food'+(entry.deleted?' deleted':'')+'" data-nutrition-entry="'+esc(entry.id)+'"><div class="nt-food-top"><h3 class="nt-food-name">'+esc(entry.name)+'</h3><div class="nt-food-calories'+(entry.calories===null?' unknown':'')+'">'+(entry.calories===null?'热量未填':kcal(entry.calories)+' kcal')+'</div></div><p class="nt-portion">'+(entry.portion?esc(entry.portion):'份量未填写')+'</p>'+(entry.food?'<p class="nt-source">'+esc(sourceText(entry.food))+'</p>':'')+(entry.note?'<p class="nt-food-note">'+esc(entry.note)+'</p>':'')+(entry.deleted?'<span class="nt-deleted-tag">已删除，不计入汇总</span>':'')+'<div class="nt-food-actions">'+(!entry.deleted?'<button class="nt-btn" type="button" data-nutrition-action="favorite" data-entry-id="'+esc(entry.id)+'">收藏</button>':'')+'<button class="nt-btn" type="button" data-nutrition-action="edit" data-entry-id="'+esc(entry.id)+'">编辑</button><button class="nt-btn" type="button" data-nutrition-action="'+(entry.deleted?'restore':'delete')+'" data-entry-id="'+esc(entry.id)+'">'+(entry.deleted?'恢复':'删除')+'</button></div></li>').join('');return '<section class="nt-meal" aria-labelledby="nutrition-meal-'+meal+'"><div class="nt-meal-head"><div><h2 id="nutrition-meal-'+meal+'">'+label+' <small class="nt-meal-state">'+({recorded:'已记录',skipped:'未进食',unrecorded:'尚未记录'}[mealState])+'</small></h2><p>'+summaryLabel(summary)+' · 已记录'+summary.entryCount+'项</p></div><button class="nt-btn" type="button" data-nutrition-add-meal="'+meal+'">添加</button></div><div class="nt-meal-tools"><button class="nt-btn" type="button" data-nutrition-copy-meal="'+meal+'">复制昨天'+label+'</button>'+(!active.length?'<button class="nt-btn" type="button" data-nutrition-skip-meal="'+meal+'">'+(mealState==='skipped'?'改为尚未记录':'标记未进食')+'</button>':'')+'</div>'+(rows?'<ul class="nt-food-list">'+rows+'</ul>':'<p class="nt-meal-empty">'+(mealState==='skipped'?'已标记这餐未进食。':'这餐尚未记录。')+'</p>')+'</section>';}).join('');}
function render(){renderSummary();renderWeek();renderMeals();renderDayStatus();renderQuick();el('content').hidden=false;controls();}
async function load(){const sequence=++state.sequence;state.controller?.abort();const controller=new AbortController();state.controller=controller;const date=state.date;el('page').setAttribute('aria-busy','true');el('content').hidden=true;controls();status('正在读取'+date+'的饮食记录…');try{const params=new URLSearchParams({date});if(state.includeDeleted)params.set('includeDeleted','1');const data=await request('/api/health/nutrition?'+params,{signal:controller.signal});if(sequence!==state.sequence)return false;if(data.date!==date||!Array.isArray(data.entries)||!data.summary||!Array.isArray(data.recent7days))throw new Error('饮食记录暂时无法读取，请重试。');state.data=data;state.today=validDay(data.today)?data.today:today();render();status('');loadFavorites();loadReview();return true;}catch(error){if(sequence!==state.sequence||error?.name==='AbortError')return false;status(error?.message||'饮食记录读取失败。',true,error?.status===401||error?.code==='SIGN_IN_REQUIRED');return false;}finally{if(sequence===state.sequence){state.controller=null;el('page').setAttribute('aria-busy','false');}}}
function formError(message,login=false){el('form-error').hidden=!message;el('form-error').innerHTML=esc(message)+(login?' <a href="'+loginLink()+'">重新登录</a>':'');}
function formStatus(message){el('form-status').hidden=!message;el('form-status').textContent=message;}
function currentText(entry){if(!entry)return '';return entry.date+' · '+meals[entry.meal]+' · '+entry.name+(entry.portion?' · '+entry.portion:'')+' · '+(entry.calories===null?'热量未填':kcal(entry.calories)+' kcal')+(entry.deleted?'（当前已删除）':'');}
function formControls(){if(!state.form)return;const editable=editableMode(),locked=state.busy||frozen();el('fields').hidden=!editable;for(const key of ['form-day','meal','name','portion','calories','note','food-search','food-search-button','food-quantity','food-unit','food-clear','discard-draft'])el(key).disabled=locked;el('food-results').querySelectorAll('button').forEach((button)=>button.disabled=locked);if(state.form.food){for(const key of ['name','portion','calories'])el(key).disabled=true;}dialog.querySelectorAll('[data-nutrition-close]').forEach((button)=>button.disabled=state.busy);el('reload-latest').hidden=state.form.mode==='create'||(!state.form.conflict&&!state.form.uncertain);el('reload-latest').disabled=state.busy||state.form.reloading;el('save').disabled=state.busy||state.form.reloading||state.form.conflict||state.form.resolved;el('save').classList.toggle('danger',state.form.mode==='delete');el('save').textContent=state.busy?'正在保存…':state.form.resolved?'已确认':frozen()?'重试原新增':state.form.mode==='delete'?'确认删除':state.form.mode==='restore'?'确认恢复':'保存食物';el('save-continue').hidden=state.form.mode!=='create'||Boolean(state.pending);el('save-continue').disabled=el('save').disabled;}
function openForm(mode,entry=null,meal='',trigger=null){if(state.busy)return;if(mode==='create'&&state.pendingError){status(state.pendingError,true);return;}state.trigger=trigger||document.activeElement;const pending=mode==='create'?state.pending:null;const draft=mode==='create'&&!entry&&state.draft&&(!meal||state.draft.meal===meal)?state.draft:null;const source=pending?.body||entry||draft;state.form={mode,entry,food:null,conflict:false,uncertain:false,reloading:false,resolved:false};state.formSequence++;el('form').reset();el('form-day').value=source?.date||state.date;el('form-day').max=state.today||today();el('meal').value=source?.meal||meal||'';el('name').value=source?.name||'';el('portion').value=source?.portion||'';el('calories').value=source?.calories??'';el('note').value=source?.note||'';el('food-search').value='';el('food-results').replaceChildren();state.foodResults=[];if(source?.food)setFormFood(foodFromSnapshot(source.food),source.food.amount,source.food.unit);else setFormFood(null);el('draft-hint').hidden=!draft;el('dialog-title').textContent=pending?'确认原新增':mode==='edit'?'编辑食物记录':mode==='delete'?'删除这条食物记录？':mode==='restore'?'恢复这条食物记录？':'添加食物';el('current-info').hidden=!entry;el('current-info').textContent=currentText(entry);formError('');formStatus(pending?'原新增结果待确认，内容已固定；重试不会新建第二条。':mode==='delete'?'确认后从当日汇总中移除。记录保留，可通过“查看已删除”恢复。':mode==='restore'?'恢复后重新计入该日期与餐次的汇总。':entry?.deleted?'这条记录已删除；编辑内容不会自动恢复。':'热量是当前份量的合计，未知可留空。');dialog.showModal();formControls();queueMicrotask(()=>{if(!editableMode()||frozen())el('save').focus();else if(state.form?.food)el('food-quantity').focus();else el(state.form?.mode==='create'?'food-search':'name').focus();});}
function editableMode(){return state.form?.mode==='create'||state.form?.mode==='edit';}
function closeForm(){if(!state.busy){captureDraft();dialog.close();}}dialog.querySelectorAll('[data-nutrition-close]').forEach((button)=>button.addEventListener('click',closeForm));dialog.addEventListener('cancel',(event)=>{if(state.busy)event.preventDefault();});dialog.addEventListener('click',(event)=>{if(event.target!==dialog||state.busy)return;const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeForm();});dialog.addEventListener('close',()=>{captureDraft();state.formSequence++;if(state.trigger?.isConnected)state.trigger.focus();});
function fields(){const date=el('form-day').value;if(!validDay(date)||date>today()){el('form-day').focus();throw new Error('请选择有效且不晚于今天的日期。');}const meal=el('meal').value;if(!Object.hasOwn(meals,meal)){el('meal').focus();throw new Error('请选择早餐、午餐、晚餐或加餐。');}let name,portion,note,amount;try{name=text(el('name').value,'食物名称',100,true);}catch(error){el('name').focus();throw error;}try{portion=text(el('portion').value,'份量',100);}catch(error){el('portion').focus();throw error;}try{amount=calories(el('calories').value);}catch(error){el('calories').focus();throw error;}try{note=text(el('note').value,'备注',500);}catch(error){el('note').focus();throw error;}const result={date,meal,name,portion,calories:amount,note};if(state.form?.food){const quantity=Number(el('food-quantity').value),unit=el('food-unit').value;const preview=foodAmount(state.form.food,quantity,unit);result.food={id:state.form.food.id,amount:quantity,unit};result.name=state.form.food.name;result.portion=String(quantity)+' '+unit;result.calories=preview.calories;}else if(state.form?.entry?.food)result.food=null;return result;}
el('reload-latest').addEventListener('click',async()=>{if(state.busy||!state.form?.entry)return;const form=state.form;form.reloading=true;formControls();const sequence=++state.formSequence;try{const data=await request('/api/health/nutrition/'+encodeURIComponent(form.entry.id));if(sequence!==state.formSequence||!dialog.open||state.form!==form)return;if(!data.entry||data.entry.id!==form.entry.id)throw new Error('最新记录暂时无法读取。');form.entry=data.entry;form.conflict=false;form.uncertain=false;form.resolved=form.mode==='delete'?data.entry.deleted:form.mode==='restore'?!data.entry.deleted:false;el('current-info').textContent='最新记录：'+currentText(data.entry);el('current-info').hidden=false;formError('');formStatus(form.resolved?'已从最新记录确认这项操作，无需重复提交。':'已读取最新记录；你的填写内容保留，请核对后再保存。');if(form.resolved)await load();}catch(error){if(sequence===state.formSequence&&dialog.open)formError(error?.message||'最新记录读取失败。',error?.status===401);}finally{if(sequence===state.formSequence){form.reloading=false;formControls();}}});
async function saveSingle(event,continueAdding=false){event?.preventDefault();const form=state.form;if(state.busy||!form||form.conflict||form.resolved)return;formError('');const creating=form.mode==='create';let body;try{if(creating){if(!state.pending)setPending({key:crypto.randomUUID(),body:fields()});body=state.pending.body;}else if(form.mode==='edit')body={...fields(),expectedRevision:form.entry.revision};else body={deleted:form.mode==='delete',expectedRevision:form.entry.revision};}catch(error){formError(error?.message||'本次未发送，请检查填写内容。');return;}state.busy=true;controls();formControls();try{const result=await request(creating?'/api/health/nutrition':'/api/health/nutrition/'+encodeURIComponent(form.entry.id),{method:creating?'POST':'PATCH',headers:{'Content-Type':'application/json',...(creating?{'Idempotency-Key':state.pending.key}:{})},body:JSON.stringify(body)});if(!result.entry||!uuid.test(result.entry.id))throw new Error('暂时无法确认保存结果，请重试原操作。');if(creating){clearPending();state.draft=null;}state.form=null;state.date=result.entry.date;if(creating&&result.entry.deleted)state.includeDeleted=true;state.busy=false;controls();dialog.close();const refreshed=await load();if(refreshed&&creating&&result.entry.deleted)status('原新增已确认；这条记录当前已删除，未恢复。');else if(refreshed&&form.mode==='delete')status('记录已删除，可勾选“查看已删除”后恢复。');if(continueAdding&&creating&&refreshed)openForm('create',null,result.entry.meal);}catch(error){if(creating&&[400,403,404,409,413,415,422].includes(error?.status)){try{clearPending();formStatus('原新增未保存，可修正内容后重新提交。');}catch{state.pendingError='原新增已明确拒绝，但确认信息暂时无法清理，请保留本页后重试。';}}else if(!creating&&error?.status===409){form.conflict=true;formStatus('记录已经变化，填写内容已保留。请读取最新记录，核对后再保存。');}else if(!creating){form.uncertain=true;formStatus('本次结果未确认；可读取最新记录确认状态，填写内容保持不变。');}const details=Array.isArray(error?.issues)?error.issues.slice(0,2).map((issue)=>issue.message).filter(Boolean).join('；'):'';formError((error?.message||'操作未完成，请重试。')+(details?' '+details:'')+(creating&&state.pending?' 原新增内容已固定，请继续确认原新增。':''),error?.status===401||error?.code==='SIGN_IN_REQUIRED');if(creating&&state.pending)formStatus('原新增结果待确认，暂时不能修改内容；重试将继续使用原请求。');}finally{state.busy=false;controls();formControls();}}
el('form').addEventListener('submit',saveSingle);el('save-continue').addEventListener('click',(event)=>saveSingle(event,true));
el('list').addEventListener('click',(event)=>{if(state.busy)return;const copy=event.target.closest('[data-nutrition-copy-meal]');if(copy){copyYesterday(copy.dataset.nutritionCopyMeal);return;}const skip=event.target.closest('[data-nutrition-skip-meal]');if(skip){updateDayStatus(skip.dataset.nutritionSkipMeal);return;}const add=event.target.closest('[data-nutrition-add-meal]');if(add){openForm('create',null,add.dataset.nutritionAddMeal,add);return;}const button=event.target.closest('[data-nutrition-action]');if(!button||state.busy)return;const entry=state.data?.entries.find((item)=>item.id===button.dataset.entryId);if(entry){if(button.dataset.nutritionAction==='favorite')favoriteEntry(entry);else openForm(button.dataset.nutritionAction,entry,'',button);}});el('add').addEventListener('click',()=>state.batchPending?openBatch([],true):openForm('create',null,'',el('add')));el('resume').addEventListener('click',()=>openForm('create',null,'',el('resume')));el('retry').addEventListener('click',load);
function chooseDate(date){if(state.busy)return;if(!validDay(date)||date>today()){el('day').value=state.date;status('请选择有效且不晚于今天的日期。',true);return;}state.date=date;load();}el('day').addEventListener('change',()=>chooseDate(el('day').value));el('previous').addEventListener('click',()=>chooseDate(shift(state.date,-1)));el('next').addEventListener('click',()=>chooseDate(shift(state.date,1)));el('today').addEventListener('click',()=>chooseDate(today()));el('include-deleted').addEventListener('change',()=>{if(state.busy)return;state.includeDeleted=el('include-deleted').checked;load();});el('week').addEventListener('click',(event)=>{const button=event.target.closest('[data-nutrition-date]');if(button&&!button.disabled)chooseDate(button.dataset.nutritionDate);});
const foodCache=new Map();
function cacheFoods(foods){for(const food of Array.isArray(foods)?foods:[])if(food&&typeof food.id==='string'&&typeof food.name==='string'&&Number.isFinite(food.kcalPer100g))foodCache.set(food.id,food);}
function foodFromSnapshot(value){if(!value)return null;const id=value.foodId||value.id;if(foodCache.has(id))return foodCache.get(id);if(!value.source||!Number.isFinite(value.kcalPer100g))return null;const food={id,name:value.foodName||'',kcalPer100g:value.kcalPer100g,state:'',source:value.source,portions:value.unit&&value.unit!=='g'&&value.amount>0?[{unit:value.unit,grams:value.grams/value.amount,estimated:value.estimated===true}]:[]};foodCache.set(id,food);return food;}
function canonicalFoodUnit(unit){const value=typeof unit==='string'?unit.trim().toLowerCase():unit;return ['g','克','公克'].includes(value)?'g':['kg','千克','公斤'].includes(value)?'kg':value;}
function unitChoices(food){const result=[{unit:'g',grams:1,label:'克（g）'},{unit:'kg',grams:1000,label:'千克（kg）'}];for(const portion of food?.portions||[])if(portion&&typeof portion.unit==='string'&&Number.isFinite(portion.grams)&&portion.grams>0&&!result.some((item)=>item.unit===portion.unit))result.push(portion);return result;}
function unitOptions(food,selected='g'){return unitChoices(food).map((item)=>'<option value="'+esc(item.unit)+'"'+(item.unit===selected?' selected':'')+'>'+esc(item.label||item.unit+(item.unit!=='g'&&item.unit!=='kg'?'（'+item.grams+'g）':''))+'</option>').join('');}
function foodAmount(food,amount,unit){const choice=unitChoices(food).find((item)=>item.unit===unit);if(!Number.isFinite(amount)||amount<=0||!choice)throw new Error('请填写有效份量，并选择有换算依据的单位。');const grams=amount*choice.grams;const tenth=Math.round(grams*food.kcalPer100g/10);if(!Number.isFinite(grams)||grams>100000||!Number.isSafeInteger(tenth)||tenth<0||tenth>200000)throw new Error('份量或热量超过支持范围，请核对。');return {grams,calories:(tenth/10).toFixed(1),estimated:choice.estimated===true};}
function setFormFood(food,amount=100,unit='g'){if(!state.form)return;state.form.food=food;el('food-selection').hidden=!food;if(food){foodCache.set(food.id,food);el('food-title').textContent=food.name+(food.state?' · '+food.state:'');el('food-source').textContent=sourceText(food)+' · 每100g '+food.kcalPer100g+' kcal';el('food-unit').innerHTML=unitOptions(food,unit);el('food-unit').value=unitChoices(food).some((item)=>item.unit===unit)?unit:'g';el('food-quantity').value=String(amount);el('name').value=food.name;updateFormCalculation();}else el('food-preview').textContent='';formControls();}
function updateFormCalculation(){if(!state.form?.food)return;try{const amount=Number(el('food-quantity').value),unit=el('food-unit').value,result=foodAmount(state.form.food,amount,unit);el('portion').value=amount+' '+unit;el('calories').value=result.calories;el('food-preview').textContent='当前份量 '+Number(result.grams.toFixed(2))+'g，合计 '+result.calories+' kcal'+(result.estimated?'（份量估算）':'')+'。保存时会由服务器按食物库核算。';}catch(error){el('calories').value='';el('food-preview').textContent=error.message;}}
function captureDraft(){if(state.form?.mode!=='create'||state.pending||state.busy)return;const name=el('name').value,portion=el('portion').value,note=el('note').value;if(!name&&!portion&&!note&&!el('calories').value&&!state.form.food){state.draft=null;return;}state.draft={date:el('form-day').value,meal:el('meal').value,name,portion,calories:el('calories').value,note,...(state.form.food?{food:{id:state.form.food.id,amount:Number(el('food-quantity').value),unit:el('food-unit').value}}:{})};}
function catalogNotice(source){if(!source||typeof source.description!=='string')return '';const link=(url,label)=>typeof url==='string'&&/^https:\/\//.test(url)?'<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">'+label+'</a>':'';return '<li class="nt-source"><details><summary>食物库来源与版本</summary><p>'+esc(source.description)+'</p><p>'+esc(source.attribution||'')+'</p><p>'+link(source.url,'官方资料')+' '+link(source.licenseUrl,'开放授权条款')+'</p></details></li>';}
async function searchFormFoods(){if(state.busy||frozen()||!state.form)return;const q=el('food-search').value.trim();if(!q){el('food-results').textContent='输入食物名称或别名，再点搜索。';return;}const sequence=++state.foodSequence,formSequence=state.formSequence;el('food-results').textContent='正在搜索食物库…';try{const data=await request('/api/health/nutrition/foods?'+new URLSearchParams({q}));if(sequence!==state.foodSequence||formSequence!==state.formSequence||!dialog.open)return;state.foodResults=Array.isArray(data.foods)?data.foods:[];cacheFoods(state.foodResults);el('food-results').innerHTML=catalogNotice(data.source)+(state.foodResults.length?state.foodResults.map((food)=>'<li><button class="nt-food-choice" type="button" data-food-id="'+esc(food.id)+'"><strong>'+esc(food.name)+'</strong><span>'+esc(food.state||food.category||'')+' · '+esc(String(food.kcalPer100g))+' kcal / 100g</span></button></li>').join(''):'没有找到匹配食物，可继续手工填写，未知热量留空。');}catch(error){if(sequence===state.foodSequence&&formSequence===state.formSequence)el('food-results').textContent=error.message;}}
el('food-search-button').addEventListener('click',searchFormFoods);el('food-search').addEventListener('keydown',(event)=>{if(event.key==='Enter'&&!event.isComposing){event.preventDefault();searchFormFoods();}});el('food-results').addEventListener('click',(event)=>{const button=event.target.closest('[data-food-id]');if(button&&!state.busy&&!frozen()){const food=foodCache.get(button.dataset.foodId);if(food){setFormFood(food);el('food-results').replaceChildren();captureDraft();}}});
el('food-clear').addEventListener('click',()=>{if(!state.busy&&!frozen()){setFormFood(null);captureDraft();}});for(const id of ['food-quantity','food-unit'])el(id).addEventListener('input',()=>{updateFormCalculation();captureDraft();});el('form').addEventListener('input',captureDraft);el('discard-draft').addEventListener('click',()=>{if(state.busy||frozen())return;state.draft=null;const meal=el('meal').value;state.form=null;dialog.close();openForm('create',null,meal);});
function renderDayStatus(){const day=state.data?.dayStatus;el('day-status-text').textContent=day?.complete?'今天的记录已标记完成。修改食物后会重新变为记录中。':'记录中：请逐餐记录或标记未进食，再标记当天已记完。';el('day-complete').textContent=day?.complete?'改为记录中':'当天已记完';}
async function updateDayStatus(meal=null){if(state.busy||!state.data?.dayStatus)return;const current=state.data.dayStatus,next={...current.meals};if(meal){const active=state.data.entries.some((item)=>item.meal===meal&&!item.deleted);if(active)return;next[meal]=next[meal]==='skipped'?'unrecorded':'skipped';}const complete=meal?false:!current.complete;if(complete&&['breakfast','lunch','dinner'].some((key)=>!['recorded','skipped'].includes(next[key]))){status('请先为早餐、午餐和晚餐添加记录或标记“未进食”。',true);return;}state.busy=true;controls();try{const result=await request('/api/health/nutrition/status',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({date:state.date,complete,meals:next,expectedRevision:current.revision})});if(!result.dayStatus||result.dayStatus.date!==state.date)throw new Error('记录状态尚未确认，请重新读取。');state.data.dayStatus=result.dayStatus;renderDayStatus();renderMeals();loadReview();status('');}catch(error){if(error.status===409)await load();status(error.message,true,error.status===401);}finally{state.busy=false;controls();}}
el('day-complete').addEventListener('click',()=>updateDayStatus());
function renderQuick(){const favorites=state.favorites||[],recent=state.data?.recentFoods||[];el('quick-list').innerHTML=(favorites.length?'<div class="nt-quick-group"><h3>常用食物</h3>'+favorites.map((item,index)=>'<div class="nt-quick-item"><button class="nt-btn" type="button" data-favorite-add="'+index+'">'+esc(item.name)+'</button><button class="nt-quick-remove" type="button" data-favorite-remove="'+esc(item.id)+'" aria-label="取消收藏'+esc(item.name)+'">×</button></div>').join('')+'</div>':'')+(recent.length?'<div class="nt-quick-group"><h3>最近吃过</h3>'+recent.map((item,index)=>'<button class="nt-btn" type="button" data-recent-add="'+index+'">'+esc(item.name)+'</button>').join('')+'</div>':'');if(!favorites.length&&!recent.length)el('quick-list').textContent='记录食物后，可在这里快速复用；食物卡片上的“收藏”可加入常用。';el('quick-list').querySelectorAll('button').forEach((button)=>button.disabled=state.busy);}
async function loadFavorites(){const date=state.date;try{const data=await request('/api/health/nutrition/favorites');if(date!==state.date)return;state.favorites=Array.isArray(data.favorites)?data.favorites:[];el('quick-status').textContent='';renderQuick();}catch(error){if(date===state.date){el('quick-status').textContent='常用食物暂时未读取成功，可重新读取页面后再试。';renderQuick();}}}
async function favoriteEntry(entry){if(state.busy||entry.deleted)return;state.busy=true;controls();try{await request('/api/health/nutrition/favorites',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({entryId:entry.id})});await loadFavorites();status('已加入常用食物。');}catch(error){status(error.message,true,error.status===401);}finally{state.busy=false;controls();renderQuick();}}
el('quick-list').addEventListener('click',async(event)=>{if(state.busy||state.pending||state.batchPending||state.pendingError)return;const remove=event.target.closest('[data-favorite-remove]');if(remove){state.busy=true;controls();try{await request('/api/health/nutrition/favorites?'+new URLSearchParams({id:remove.dataset.favoriteRemove}),{method:'DELETE'});await loadFavorites();}catch(error){status(error.message,true,error.status===401);}finally{state.busy=false;controls();renderQuick();}return;}const favorite=event.target.closest('[data-favorite-add]'),recent=event.target.closest('[data-recent-add]');const entry=favorite?state.favorites[Number(favorite.dataset.favoriteAdd)]:recent?state.data?.recentFoods?.[Number(recent.dataset.recentAdd)]:null;if(entry)openForm('create',{...entry,date:state.date,meal:entry.meal||''},'',event.target);});
function toDraft(entry){const foodItem=foodFromSnapshot(entry.food);return {amount:entry.amount??entry.food?.amount??null,unit:canonicalFoodUnit(entry.unit??entry.food?.unit??null),date:entry.date||state.date,meal:entry.meal||'',name:entry.name||'',portion:entry.portion||'',calories:entry.calories??null,note:entry.note||'',food:entry.food?{id:entry.food.foodId||entry.food.id,amount:entry.food.amount,unit:canonicalFoodUnit(entry.food.unit)}:null,candidates:foodItem?[foodItem]:Array.isArray(entry.candidates)?entry.candidates:[],warnings:Array.isArray(entry.warnings)?entry.warnings:[],foodItem};}
async function copyYesterday(meal){if(state.batchRows.length&&!state.batchPending){openBatch();return;}if(state.busy||state.pending||state.batchPending||state.pendingError){status('请先确认尚未完成的新增。',true);return;}if(state.date<='1970-01-01'){status('这一天没有可复制的前一天。',true);return;}const date=state.date;state.busy=true;controls();try{const data=await request('/api/health/nutrition?'+new URLSearchParams({date:shift(date,-1)}));if(date!==state.date)return;const entries=(data.entries||[]).filter((item)=>item.meal===meal&&!item.deleted);if(!entries.length){status('昨天'+meals[meal]+'没有可复制的食物记录。');return;}if(entries.length>30)throw new Error('昨天这餐超过30项，请分批添加。');state.busy=false;openBatch(entries.map((entry)=>toDraft({...entry,date})));}catch(error){status(error.message,true,error.status===401);}finally{state.busy=false;controls();}}
function batchError(message){el('batch-error').hidden=!message;el('batch-error').textContent=message;}
function batchControls(){const locked=state.busy||Boolean(state.batchPending);el('batch-rows').querySelectorAll('input,select,textarea,button').forEach((node)=>node.disabled=locked);el('batch-discard').disabled=state.busy||Boolean(state.batchPending);el('batch-save').disabled=state.busy||(!state.batchPending&&!state.batchRows.length);el('batch-save').textContent=state.busy?'正在保存…':state.batchPending?'重试原批次':'保存全部食物';el('batch-dialog').querySelectorAll('[data-nutrition-batch-close]').forEach((node)=>node.disabled=state.busy);}
function batchMealOptions(selected){return '<option value="">选择餐次</option>'+Object.entries(meals).map(([key,label])=>'<option value="'+key+'"'+(key===selected?' selected':'')+'>'+label+'</option>').join('');}
function renderBatchRows(){el('batch-rows').innerHTML=state.batchRows.map((row,index)=>{const item=row.foodItem,foodOptions='<option value="">手工填写 / 热量待补充</option>'+row.candidates.map((food)=>'<option value="'+esc(food.id)+'"'+(row.food?.id===food.id?' selected':'')+'>'+esc(food.name)+(food.state?' · '+esc(food.state):'')+'</option>').join('');return '<article class="nt-batch-row" data-draft-index="'+index+'"><div class="nt-batch-head"><h3>食物 '+(index+1)+'</h3><button type="button" class="nt-btn" data-draft-remove="'+index+'">移除</button></div><div class="nt-batch-grid" data-draft-fields><label>日期<input class="nt-control" type="date" data-draft-field="date" value="'+esc(row.date)+'" min="1970-01-01" max="'+today()+'"></label><label>餐次<select class="nt-control" data-draft-field="meal">'+batchMealOptions(row.meal)+'</select></label><label class="nt-full">匹配食物<select class="nt-control" data-draft-field="candidate">'+foodOptions+'</select></label><div class="nt-full nt-draft-search"><input class="nt-control" data-draft-query placeholder="搜索食物库替换匹配" aria-label="搜索第'+(index+1)+'项食物"><button class="nt-btn" type="button" data-draft-search="'+index+'">搜索</button></div><label class="nt-full">食物名称<input class="nt-control" maxlength="100" data-draft-field="name" value="'+esc(row.name)+'"'+(item?' readonly':'')+'></label>'+(item?'<label>数量<input class="nt-control" type="number" min="0.001" step="any" data-draft-field="amount" value="'+esc(String(row.food?.amount??''))+'"></label><label>单位<select class="nt-control" data-draft-field="unit">'+unitOptions(item,row.food?.unit||'g')+'</select></label>':'')+'<label>份量<input class="nt-control" data-draft-field="portion" maxlength="100" value="'+esc(row.portion)+'"'+(item?' readonly':'')+'></label><label>合计热量 kcal<input class="nt-control" inputmode="decimal" data-draft-field="calories" value="'+esc(row.calories??'')+'" placeholder="未知留空"'+(item?' readonly':'')+'></label><label class="nt-full">备注<input class="nt-control" data-draft-field="note" maxlength="500" value="'+esc(row.note)+'"></label></div><p class="nt-source" data-draft-preview>'+esc(item?sourceText(item)+' · 每100g '+item.kcalPer100g+' kcal':'手工记录，热量未知时留空。')+'</p>'+(row.warnings.length?'<ul class="nt-warning">'+row.warnings.map((warning)=>'<li>'+esc(warning)+'</li>').join('')+'</ul>':'')+'</article>';}).join('');batchControls();}
function openBatch(rows=[],resume=false){if(state.busy||state.pendingError)return;if(state.pending){status('请先确认尚未完成的单项新增。',true);return;}if(state.batchPending){state.batchRows=state.batchPending.body.entries.map(toDraft);}else if(rows.length){state.batchRows=rows.map((row)=>{const draft=toDraft(row);cacheFoods(draft.candidates);if(draft.food){draft.foodItem=foodCache.get(draft.food.id)||draft.foodItem;if(draft.foodItem&&!draft.candidates.some((food)=>food.id===draft.food.id))draft.candidates.unshift(draft.foodItem);}return draft;});}if(!state.batchRows.length){status('没有待保存的食物草稿。');return;}el('batch-title').textContent=state.batchPending?'确认原批量新增':'核对食物明细';el('batch-status').textContent=state.batchPending?'原提交已固定，重试会继续确认同一批食物，不会重复新增。':'核对日期、餐次和份量。未匹配食物可手填，未知热量留空。';batchError('');renderBatchRows();el('batch-dialog').showModal();renderPending();}
function rowBody(row){if(!validDay(row.date)||row.date>today())throw new Error('请选择有效且不晚于今天的日期。');if(!Object.hasOwn(meals,row.meal))throw new Error('请为每项食物选择餐次。');const body={date:row.date,meal:row.meal,name:text(row.name,'食物名称',100,true),portion:text(row.portion,'份量',100),calories:calories(row.calories),note:text(row.note,'备注',500)};if(row.food&&row.foodItem){const result=foodAmount(row.foodItem,Number(row.food.amount),row.food.unit);body.name=row.foodItem.name;body.portion=row.food.amount+' '+row.food.unit;body.calories=result.calories;body.food={id:row.foodItem.id,amount:Number(row.food.amount),unit:row.food.unit};}return body;}
function updateDraftCalculation(row,node){if(!row.foodItem||!row.food)return;const preview=node.querySelector('[data-draft-preview]');try{const value=foodAmount(row.foodItem,Number(row.food.amount),row.food.unit);row.portion=row.food.amount+' '+row.food.unit;row.calories=value.calories;node.querySelector('[data-draft-field="portion"]').value=row.portion;node.querySelector('[data-draft-field="calories"]').value=row.calories;preview.textContent=sourceText(row.foodItem)+' · 当前 '+Number(value.grams.toFixed(2))+'g · '+value.calories+' kcal'+(value.estimated?'（份量估算）':'');}catch(error){row.calories=null;node.querySelector('[data-draft-field="calories"]').value='';preview.textContent=error.message;}}
function retainedDraftAmount(row,item){const canonical=(unit)=>['g','克','公克'].includes(unit)?'g':['kg','千克','公斤'].includes(unit)?'kg':unit;const source=row.food||{amount:row.amount,unit:row.unit};if(Number.isFinite(source.amount)&&source.amount>0){const unit=canonical(source.unit);if(unit==='g'||unit==='kg'||(unitChoices(item).some((choice)=>choice.unit===unit)&&(unit!=='参考单位'||row.food?.id===item.id)))return {amount:source.amount,unit};}const match=String(row.portion||'').match(/^\s*(\d+(?:\.\d+)?)\s*(kg|g|千克|公斤|公克|克)\s*$/i);return match&&Number(match[1])>0?{amount:Number(match[1]),unit:canonical(match[2].toLowerCase())}:null;}
el('batch-rows').addEventListener('input',(event)=>{if(state.busy||state.batchPending)return;const field=event.target.dataset.draftField,node=event.target.closest('[data-draft-index]');if(!field||!node)return;const row=state.batchRows[Number(node.dataset.draftIndex)];if(!row)return;if(field==='candidate'){const item=foodCache.get(event.target.value),measurement=item?retainedDraftAmount(row,item):null;row.foodItem=item||null;row.food=item?{id:item.id,amount:measurement?.amount??null,unit:measurement?.unit||'g'}:null;if(item){row.name=item.name;row.amount=row.food.amount;row.unit=row.food.unit;if(measurement){row.portion=measurement.amount+' '+measurement.unit;row.calories=foodAmount(item,measurement.amount,measurement.unit).calories;}else{row.portion='份量待补充';row.calories=null;const warning='请补充这项食物的实际克重；未自动假设份量。';if(!row.warnings.includes(warning))row.warnings.push(warning);}}else row.calories=null;renderBatchRows();}else if(field==='amount'||field==='unit'){if(row.food){row.food[field]=field==='amount'?Number(event.target.value):event.target.value;row.amount=row.food.amount;row.unit=row.food.unit;updateDraftCalculation(row,node);}}else{row[field]=event.target.value;if(field==='portion'){row.amount=null;row.unit=null;}}});
el('batch-rows').addEventListener('keydown',(event)=>{if(event.key==='Enter'&&!event.isComposing&&event.target.matches('[data-draft-query]')){event.preventDefault();event.target.closest('[data-draft-index]').querySelector('[data-draft-search]').click();}});
el('batch-rows').addEventListener('change',(event)=>{if(event.target.matches('[data-draft-field="candidate"],[data-draft-field="meal"],[data-draft-field="unit"],[data-draft-field="date"]'))event.target.dispatchEvent(new Event('input',{bubbles:true}));});
el('batch-rows').addEventListener('click',async(event)=>{if(state.busy||state.batchPending)return;const remove=event.target.closest('[data-draft-remove]');if(remove){state.batchRows.splice(Number(remove.dataset.draftRemove),1);renderBatchRows();renderPending();return;}const button=event.target.closest('[data-draft-search]');if(!button)return;const index=Number(button.dataset.draftSearch),row=state.batchRows[index],node=button.closest('[data-draft-index]'),q=node.querySelector('[data-draft-query]').value.trim();if(!q)return;button.disabled=true;try{const data=await request('/api/health/nutrition/foods?'+new URLSearchParams({q}));if(!el('batch-dialog').open||state.batchRows[index]!==row||state.batchPending)return;row.candidates=Array.isArray(data.foods)?data.foods:[];cacheFoods(row.candidates);if(row.foodItem&&!row.candidates.some((food)=>food.id===row.foodItem.id))row.candidates.unshift(row.foodItem);row.warnings=row.candidates.length?['搜索结果已更新，请选择符合生熟状态和食物种类的条目。']:['未找到匹配项，可手工填写，热量未知时留空。'];renderBatchRows();}catch(error){batchError(error.message);}finally{button.disabled=false;}});
el('batch-form').addEventListener('submit',async(event)=>{event.preventDefault();if(state.busy)return;batchError('');let operation;try{if(!state.batchPending){if(!state.batchRows.length||state.batchRows.length>30)throw new Error('每批请保留1至30项食物。');const entries=state.batchRows.map((row,index)=>{try{return rowBody(row);}catch(error){throw new Error('第'+(index+1)+'项：'+error.message);}});operation={key:crypto.randomUUID(),body:{entries}};sessionStorage.setItem(batchKey,JSON.stringify(operation));state.batchPending=operation;}operation=state.batchPending;}catch(error){batchError(error.message||'未发送，请检查内容或浏览器存储。');return;}state.busy=true;controls();batchControls();try{const result=await request('/api/health/nutrition/batch',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':operation.key},body:JSON.stringify(operation.body)});if(!Array.isArray(result.entries)||result.entries.length!==operation.body.entries.length||result.entries.some((entry)=>!uuid.test(entry.id)))throw new Error('保存结果尚未确认，请重试原批次。');sessionStorage.removeItem(batchKey);state.batchPending=null;state.batchRows=[];state.date=result.entries[0].date;state.busy=false;el('batch-dialog').close();await load();status('已保存 '+result.entries.length+' 项食物。');}catch(error){if([400,403,404,409,413,415,422].includes(error.status)){try{sessionStorage.removeItem(batchKey);state.batchPending=null;el('batch-status').textContent='本批未保存，可修正内容后重新提交。';}catch{state.pendingError='原批次已被拒绝，但确认信息暂时无法清理，请保留本页。';}}else el('batch-status').textContent='保存结果待确认，原内容已固定。重试会使用原批次，不会重复新增。';batchError(error.message||'批量保存没有完成，请重试原批次。');}finally{state.busy=false;controls();batchControls();renderPending();}});
el('batch-dialog').querySelectorAll('[data-nutrition-batch-close]').forEach((button)=>button.addEventListener('click',()=>{if(!state.busy){el('batch-dialog').close();renderPending();}}));el('batch-dialog').addEventListener('cancel',(event)=>{if(state.busy)event.preventDefault();});el('batch-dialog').addEventListener('close',renderPending);el('resume-batch').addEventListener('click',()=>openBatch([],true));el('batch-discard').addEventListener('click',()=>{if(state.busy||state.batchPending)return;state.batchRows=[];el('batch-dialog').close();renderPending();});
el('ai-parse').addEventListener('click',async()=>{if(state.busy||state.pending||state.batchPending||state.pendingError||state.batchRows.length)return;const input=el('ai-text').value.trim();el('ai-status').hidden=false;if(!input||input.length>2000){el('ai-status').textContent='请填写1至2000个字符的饮食描述。';el('ai-text').focus();return;}const date=state.date,meal=el('ai-meal').value;state.busy=true;controls();el('ai-status').textContent='正在理解食物和份量，并匹配食物库…';const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),65000);try{const data=await request('/api/health/nutrition/parse',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({text:input,date,...(Object.hasOwn(meals,meal)?{meal}:{})})});if(!Array.isArray(data.drafts)||!data.drafts.length||data.drafts.length>20||data.drafts.some((draft)=>typeof draft.name!=='string'||!validDay(draft.date)))throw new Error('识别结果不完整，请调整描述后重试。');state.busy=false;el('ai-status').textContent='已拆解 '+data.drafts.length+' 项，请核对明细后保存。'+(Array.isArray(data.warnings)?data.warnings.join(' '):'');openBatch(data.drafts);}catch(error){el('ai-status').textContent=error.name==='AbortError'?'识别等待超过65秒。请求可能已产生API费用，请稍后再试。':error.message||'这次识别未完成，请稍后再试。';}finally{clearTimeout(timer);state.busy=false;controls();}});
async function loadReview(){const sequence=++state.reviewSequence,date=state.date,days=state.reviewDays;el('review-status').textContent='正在读取饮食回顾…';el('review-summary').replaceChildren();el('review-chart').replaceChildren();el('review-meals').replaceChildren();el('review-notes').textContent='';document.querySelectorAll('[data-nutrition-review-days]').forEach((button)=>button.setAttribute('aria-pressed',String(Number(button.dataset.nutritionReviewDays)===days)));try{const data=await request('/api/health/nutrition/review?'+new URLSearchParams({date,days:String(days)}));if(sequence!==state.reviewSequence||date!==state.date)return;if(!data.summary||!Array.isArray(data.days)||data.days.length>30||!Array.isArray(data.meals))throw new Error('回顾数据暂时无法读取。');const summary=data.summary;el('review-status').textContent=data.range.from+' — '+data.range.to+' · 已记录部分';el('review-summary').innerHTML='<p>有记录 <strong>'+Number(summary.recordedDays)+' 天</strong> · 已记完 <strong>'+Number(summary.completeDays)+' 天</strong> · '+Number(summary.unknownCount)+' 项热量未填</p><p>完整且热量已填的日均值：<strong>'+(summary.averageCompleteKcal===null?'暂无可比较日期':kcal(summary.averageCompleteKcal)+' kcal')+'</strong>（'+Number(summary.comparableDays)+' 天）</p>';const values=data.days.map((day)=>typeof day.knownCalories==='string'?Number(day.knownCalories):null),max=Math.max(1,...values.filter((value)=>value!==null&&Number.isFinite(value)));el('review-chart').innerHTML='<div class="nt-bar-chart">'+data.days.map((day,index)=>{const value=values[index],known=value!==null&&Number.isFinite(value),height=known?Math.max(0,Math.min(100,value/max*100)):0,label=day.date+'，'+(known?'已填 '+kcal(day.knownCalories)+' kcal':'无已填热量')+(day.unknownCount?'，'+day.unknownCount+'项热量未填':'')+(day.complete?'，已记完':'，记录可能不完整');return '<button type="button" class="nt-chart-day'+(!known?' is-missing':!day.complete||day.unknownCount?' is-incomplete':'')+'" data-review-date="'+esc(day.date)+'" title="'+esc(label)+'" aria-label="'+esc(label)+'"><span class="nt-bar-track"><span class="nt-bar" style="height:'+height+'%;min-height:0"></span></span><span>'+esc(day.date.slice(5))+'</span><small>'+(known?Math.round(value):'—')+'</small></button>';}).join('')+'</div>';el('review-meals').innerHTML=data.meals.map((meal)=>'<p>'+esc(meal.label||meals[meal.meal]||'餐次')+'：'+(meal.knownCalories===null?'热量未填':kcal(meal.knownCalories)+' kcal')+' · '+Number(meal.entryCount)+' 项</p>').join('');el('review-notes').textContent=(data.limitations||[]).filter((note)=>typeof note==='string').join(' ');el('review-assistant').dataset.healthChatPrompt='请总结'+data.range.from+'至'+data.range.to+'的饮食记录，说明覆盖情况和可以尝试的小建议。';}catch(error){if(sequence===state.reviewSequence)el('review-status').textContent=error.message||'回顾暂时不可用。';}}
document.querySelectorAll('[data-nutrition-review-days]').forEach((button)=>button.addEventListener('click',()=>{state.reviewDays=Number(button.dataset.nutritionReviewDays)===30?30:7;loadReview();}));el('review-chart').addEventListener('click',(event)=>{const button=event.target.closest('[data-review-date]');if(button)chooseDate(button.dataset.reviewDate);});

function restoreUrl(){const params=new URLSearchParams(location.search);state.today=today();const date=params.get('date');state.date=validDay(date)&&date<=state.today?date:state.today;state.includeDeleted=params.get('includeDeleted')==='1';}window.addEventListener('popstate',()=>{if(state.busy){controls();return;}restoreUrl();load();});window.addEventListener('pageshow',(event)=>{if(event.persisted&&!state.busy)load();});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&!state.busy)load();});try{state.pending=readPending();state.batchPending=readBatchPending();}catch(error){state.pendingError=error?.message||'暂时无法读取上次新增的确认信息。';}restoreUrl();load();
`;

export function renderNutritionScript(ownerId: string): string {
  const slash = String.fromCharCode(92);
  const data = JSON.stringify(ownerId).replaceAll('<', slash + 'u003c').replaceAll(String.fromCharCode(0x2028), slash + 'u2028').replaceAll(String.fromCharCode(0x2029), slash + 'u2029');
  return `<script type="module">(()=>{const ownerId=${data};${NUTRITION_SCRIPT}})();</script>`;
}
